from app.core.settings import get_guardrails
from datetime import UTC, datetime, timedelta
from typing import Any
from uuid import UUID, uuid4

import psycopg
from psycopg import Connection



class ActiveRunError(RuntimeError):
    pass


class ResumeTokenError(ValueError):
    pass


class ResumeTokenExpired(ResumeTokenError):
    """유효한 토큰의 대기 기간만 만료되었다."""


class ResumeRequestConflict(ValueError):
    """같은 요청 식별자를 다른 입력에 재사용했다."""


class CaseService:
    def __init__(self, *, graph_revision: str = "controller-v1") -> None:
        self.graph_revision = graph_revision

    def start_run(self, conn: Connection, *, tenant_id: str, case_id: UUID) -> UUID:
        run_id = uuid4()
        with conn.cursor() as cur:
            cur.execute(
                "SELECT 1 FROM agent_runs WHERE tenant_id=%s AND case_id=%s "
                "AND status IN ('active','running','resuming') LIMIT 1 FOR UPDATE",
                (tenant_id, case_id),
            )
            if cur.fetchone() is not None:
                raise ActiveRunError(f"active run already exists for case {case_id}")
            try:
                cur.execute(
                    "INSERT INTO agent_runs(run_id,tenant_id,case_id,graph_revision,status,started_at) "
                    "VALUES(%s,%s,%s,%s,'active',now()) RETURNING run_id",
                    (run_id, tenant_id, case_id, self.graph_revision),
                )
            except psycopg.errors.UniqueViolation as exc:
                # The SELECT above only locks an already-existing row. The
                # partial unique index is the race-safe guard for two empty
                # active-run sets, and exposes the same application failure.
                raise ActiveRunError(f"active run already exists for case {case_id}") from exc
        return run_id

    def finish_run(self, conn: Connection, run_id: UUID, status: str = "succeeded") -> None:
        with conn.cursor() as cur:
            cur.execute("UPDATE agent_runs SET status=%s, finished_at=now() WHERE run_id=%s", (status, run_id))

    def checkpoint(self, *, case_id: UUID, run_id: UUID, node_name: str, runtime_state: dict[str, Any] | None = None) -> dict[str, Any]:
        # Deliberately not a business-state snapshot. A graph checkpoint is disposable.
        return {"case_id": str(case_id), "run_id": str(run_id), "graph_revision": self.graph_revision,
                "node_name": node_name, "runtime_state": dict(runtime_state or {})}

    @staticmethod
    def new_resume_token() -> str:
        return secrets.token_urlsafe(32)

    @staticmethod
    def token_hash(token: str) -> str:
        return hashlib.sha256(token.encode("utf-8")).hexdigest()

    def resume_metadata(self, token: str, wait_reason: str) -> dict[str, Any]:
        return {"resume_token_hash": self.token_hash(token),
                "resume_token_expires_at": (
                    # ★가드레일에서 읽는다. 24 가 박혀 있어
                    #   `resume.token_ttl_hours` 를 낮춰도 아무 일이 없었다 —
                    #   보안 한도를 조인 줄 알게 되는 종류다(2026-09-03).
                    datetime.now(UTC)
                    + timedelta(hours=float(get_guardrails().get("resume.token_ttl_hours")))
                ).isoformat(),
                "resume_token_used": False, "wait_reason": wait_reason}

    def validate_resume(self, case: dict[str, Any], token: str, *, event_id: str | None = None,
                        message_hash: str | None = None) -> str | None:
        return self._validate_resume_hash(case, self.token_hash(token), event_id=event_id,
                                          message_hash=message_hash)

    def validate_customer_input(self, case: dict[str, Any], *, event_id: str | None,
                                message_hash: str | None) -> str | None:
        """고객 소유권을 확인한 내부 웹 입구만 사용한다."""
        state = case.get("state_json") or {}
        # 이미 소비한 요청의 재전송은 종료 상태에서도 같은 결과를 반환한다.
        recorded = next((r for r in state.get("resume_requests", [])
                         if event_id and r["request_id"] == event_id), None)
        if recorded is not None:
            return self._validate_resume_hash(case, recorded["token_hash"], event_id=event_id,
                                              message_hash=message_hash)
        if str(case["status"]) != "waiting_input" or state.get("wait_reason") != "customer_input":
            raise ResumeTokenError("case is not waiting for customer input")
        token_hash = state.get("resume_token_hash")
        if not token_hash:
            raise ResumeTokenError("invalid resume token metadata")
        return self._validate_resume_hash(case, token_hash, event_id=event_id,
                                          message_hash=message_hash)

    def _validate_resume_hash(self, case: dict[str, Any], token_hash: str, *,
                              event_id: str | None, message_hash: str | None) -> str | None:
        state = case.get("state_json") or {}
        for request in state.get("resume_requests", []):
            if event_id and request["request_id"] == event_id:
                if request["token_hash"] != token_hash:
                    raise ResumeTokenError("invalid resume token")
                if request.get("message_hash") != message_hash:
                    raise ResumeRequestConflict("resume request id reused with different message")
                return "idempotent"
        # 이전 판에서 만든 콜백·승인 재개 기록도 계속 읽는다.
        if event_id and state.get("last_resume_event_id") == event_id:
            if state.get("resume_token_hash") == token_hash and message_hash is None:
                return "idempotent"
            raise ResumeRequestConflict("resume request id reused with different message")
        if state.get("resume_token_used"):
            raise ResumeTokenError("resume token has already been used")
        if state.get("resume_token_hash") != token_hash:
            raise ResumeTokenError("invalid resume token")
        expires = datetime.fromisoformat(state["resume_token_expires_at"])
        if expires.tzinfo is None:
            expires = expires.replace(tzinfo=UTC)
        if datetime.now(UTC) >= expires:
            raise ResumeTokenExpired("resume token expired")
        return None

    ★이름이 중립이다. 무엇을 가리키는지는 조립이 주입한 확인기가 안다.
    """
    model_config = ConfigDict(extra="forbid")
    kind: str = Field(min_length=1)
    id: UUID
    part_id: UUID | None = None
    base_version: int | None = Field(default=None, ge=1)
    request: dict[str, Any] | None = None


class MessageRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")
    request_id: str
    message: str = Field(min_length=1)
    token: str | None = Field(default=None, min_length=1)
    expected_version: int | None = None


class ApprovalRequest(BaseModel):
    model_config = ConfigDict(extra="forbid")
    decision: str
    approver_id: str
    note: str | None = None


def _error(status: int, code: str, message: str) -> HTTPException:
    return HTTPException(status, {"error": {"code": code, "message": message}})


def _case_or_404(conn, principal: Principal, case_id: UUID, customer_id: UUID | None = None):
    case = repository.get_case(conn, tenant_id=principal.tenant_id, case_id=case_id)
    if case is None or (customer_id is not None and case["customer_id"] != customer_id):
        raise _error(404, "not_found", "resource not found")
    return case


def _view(case: dict[str, Any]) -> dict[str, Any]:
    return {"case_id": str(case["case_id"]), "status": str(case["status"]), "version": case["version"],
            "intent": case.get("intent"), "issue_code": case.get("issue_code"), "sentiment": case.get("sentiment"),
            "links": {"self": f"/v1/cases/{case['case_id']}"}}


def _run_case_detached(controller: Any, *, tenant_id: str, case_id: UUID, actor_id: str) -> None:
    """접수 응답을 보낸 **뒤에** 에이전트를 돌린다.

    ★왜 뗐나: 전에는 접수 라우트가 `run_case()` 를 그 자리에서 기다렸다. 실측
      p50 20~34초 · p95 32~51초 — 고객이 문의를 넣고 그만큼 붙잡혀 있었다
      (v8 §3-A [2026-09-01 교정]). 접수는 "받았다" 를 빨리 답하는 일이고,
      처리는 그 뒤의 일이다.

    ★실패를 삼키지 않는다. 떼어낸 실행은 아무도 안 보므로 조용히 죽기 쉽다 —
      그래서 `exception()` 으로 스택까지 남긴다. Case 는 `routing` 에 남아
      운영 화면에서 보인다.

    ★남은 구멍(정직하게 적는다): `routing` 에 남은 Case 를 되잡는 sweeper 는
      아직 없다. `classifying` 쪽과 같은 성격의 후속 과제다.
    """
    try:
        outcome = controller.run_case(tenant_id=tenant_id, case_id=case_id, actor_id=actor_id)
        if inspect.isawaitable(outcome):
            asyncio.run(outcome)
    except Exception:
        logger.exception("detached run_case failed: tenant=%s case=%s", tenant_id, case_id)


def build_router(classifier: Classifier | None = None, controller: Any | None = None,
                 subject_resolver: Callable[..., Any] | None = None,
                 subject_interpreter: Callable[..., Any] | None = None) -> APIRouter:
    router = APIRouter()
    @router.post("/v1/cases", status_code=201)
    def create(request: CreateCase, background: BackgroundTasks,
               principal: Principal = Depends(require_scope("case:write"))):
        tenant = principal.tenant_id
        # ★절차는 코어 1 의 접수 함수가 갖는다(`app/application/case_intake.py`) — 감시 루프가
        #   여는 시스템 Case 와 같은 문을 지난다. 이 라우트는 HTTP 로 옮기기만 한다.
        #   멱등·잠금·「분류는 생성 트랜잭션 밖」 규칙은 그 함수에 그대로 옮겼다
        #   (옮기기 전 경위 주석은 git 이력 `cases.py` 2026-09-16 판에 있다).
        subject = request.subject_ref.model_dump(mode="json") if request.subject_ref else None
        with get_connection() as conn:
            try:
                opened = open_case(conn, repository=repository, tenant_id=tenant,
                                   customer_id=request.customer_id, request_id=request.request_id,
                                   message=request.message, channel=request.channel,
                                   actor_type="api", actor_id=principal.key_id,
                                   idempotency_key=request.idempotency_key, subject_ref=subject,
                                   subject_resolver=subject_resolver, classifier=classifier,
                                   subject_interpreter=subject_interpreter)
            except IdempotencyConflict as exc:
                raise _error(409, "idempotency_key_reused", str(exc)) from exc
            except SubjectNotFound as exc:
                raise _error(404, "not_found", "resource not found") from exc
            except SubjectUnsupported as exc:
                raise _error(422, "subject_ref_unsupported", str(exc)) from exc
            case_id = opened.case_id
            saved = repository.get_case(conn, tenant_id=tenant, case_id=case_id)
            view = _view(saved)
            if controller is not None and view["status"] == "routing" and hasattr(controller, "_capability"):
                try:
                    controller._capability(saved)
                except TeamUnavailable as exc:
                    failure = team_unavailable_error(exc)
                    failure.detail["error"]["case_id"] = str(case_id)
                    raise failure from exc
                except RegistryError:
                    # 담당 재분류는 Controller의 기존 절차가 처리한다.
                    pass
            should_start = opened.created
            if not opened.created and view["status"] == "routing":
                with conn.cursor() as cur:
                    cur.execute("SELECT 1 FROM agent_runs WHERE tenant_id=%s AND case_id=%s LIMIT 1",
                                (tenant, case_id))
                    should_start = cur.fetchone() is None
            if not should_start:
                return view
        if controller is not None and view["status"] == "routing":
            # ★응답을 보낸 **뒤에** 돌린다. 접수는 "받았다" 를 빨리 답하는 일이다.
            #   진행 결과는 `GET /v1/cases/{case_id}` 로 확인한다 — 그래서 아래
            #   응답에는 run 관련 필드(`run_id`·`next_action`·`resume_token`)가
            #   들어가지 않는다. 있다가 없다가 하는 필드를 두면 클라이언트가
            #   "없으면 실패" 로 잘못 읽는다.
            background.add_task(_run_case_detached, controller, tenant_id=tenant,
                                case_id=case_id, actor_id=principal.key_id)
        return view

    @router.get("/v1/cases")
    def list_cases(customer_id: UUID = Query(...), limit: int = Query(20, ge=1, le=100), principal: Principal = Depends(require_scope("case:read"))):
        with get_connection() as conn:
            rows = repository.list_cases(conn, tenant_id=principal.tenant_id, customer_id=customer_id, limit=limit)
        return [{k: (str(v) if isinstance(v, UUID) else v) for k, v in row.items()} for row in rows]

    @router.get("/v1/cases/{case_id}")
    def detail(case_id: UUID, customer_id: UUID | None = Query(None), principal: Principal = Depends(require_scope("case:read"))):
        with get_connection() as conn:
            case = _case_or_404(conn, principal, case_id, customer_id)
            events = repository.get_case_events(conn, tenant_id=principal.tenant_id, case_id=case_id)
        availability = {}
        if controller is not None and case["status"] in ("routing", "running", "resuming", "waiting_input", "waiting_approval") and hasattr(controller, "_capability"):
            try:
                controller._capability(case)
            except TeamUnavailable as exc:
                availability["execution_error"] = team_unavailable_error(exc).detail["error"]
            except RegistryError:
                pass
        return {**_view(case), **availability, "answer": case["state_json"].get("answer"), "pending_actions": [],
                # ★2026-09-01 발견 — value 가 항상 {} 로 하드코딩돼 있었다.
                #   get_case_events() 는 payload_json 을 이미 가져오는데 여기서 버렸다.
                #   그러면 API 는 "무슨 단계를 지났다"만 말하고 "무엇을 근거로 그렇게
                #   판단했나"는 말하지 않는다 — 되짚기가 화면에서만 되고 API 로는 안 됐다.
                "evidence": [{"source_type": "case_event", "source_id": str(e["event_id"]), "claim": e["event_type"], "value": e["payload_json"] or {}, "observed_at": e["created_at"]} for e in events]}

    @router.post("/v1/cases/{case_id}/messages")
    def message(case_id: UUID, request: MessageRequest, principal: Principal = Depends(require_scope("case:write"))):
        if controller is None:
            raise _error(500, "misconfigured", "controller not configured for resume")
        with get_connection() as conn:
            _case = _case_or_404(conn, principal, case_id)
        try:
            common = dict(tenant_id=principal.tenant_id, case_id=case_id,
                          actor_id=principal.key_id, event_id=request.request_id,
                          message=request.message, expected_version=request.expected_version)
            if request.token is not None:
                outcome = controller.resume(token=request.token, **common)
            else:
                # case:write 주체가 조회할 수 있는 동일 테넌트 업무의 고객 입력만 재개한다.
                outcome = controller.resume_customer_input(customer_id=_case["customer_id"], **common)
            if inspect.isawaitable(outcome):
                outcome = asyncio.run(outcome)
        except TeamUnavailable as exc:
            raise team_unavailable_error(exc) from exc
        except ControllerError as exc:
            raise _error(401, "invalid_resume_token", str(exc)) from exc
        except ValueError as exc:
            raise _error(422, "invalid_customer_input", str(exc)) from exc
        except StateConflict as exc:
            raise _error(409, "state_conflict", "state conflict") from exc
        except InvalidTransition as exc:
            raise _error(422, "invalid_transition", "invalid state transition") from exc
        with get_connection() as conn:
            updated = repository.get_case(conn, tenant_id=principal.tenant_id, case_id=case_id)
            state = updated.get("state_json") or {}
            return {**_view(updated), "answer": state.get("answer"),
                    "required_input_schema": state.get("required_input_schema"),
                    "resume_token": outcome.get("resume_token") if isinstance(outcome, dict) else None}

    @router.post("/v1/cases/{case_id}/actions/{action_id}/approve")
    def approve(case_id: UUID, action_id: UUID, request: ApprovalRequest, principal: Principal = Depends(require_scope("action:approve"))):
        if request.decision not in {"approved", "rejected"}: raise _error(400, "contract_violation", "invalid decision")
        with get_connection() as conn:
            case = _case_or_404(conn, principal, case_id)
            idem = idempotency_key(tenant_id=principal.tenant_id, request_id=request.approver_id, action_type="action.approve", business_subject=f"{action_id}:{request.decision}")

            # ★v7 §9-E — 검증은 두 번이다. 여기가 두 번째, **실행 직전 재검증**이다.
            #   제안 생성 때 맞았어도 사람이 승인 버튼을 누르는 사이에
            #   잔액·구독 상태가 바뀔 수 있다.
            #
            # ★승인 트랜잭션 **밖**에서 한다. 안에서 하고 409 를 던졌더니
            #   방금 쓴 escalated 이벤트가 예외와 함께 **롤백돼 사라졌다** —
            #   "조용히 무시하지 않는다" 가 그대로 깨졌다. 거부 기록은 남아야 한다.
            # ★존재 확인이 먼저다. 없는 action 에 재검증을 돌리면
            #   404 여야 할 요청이 엉뚱한 상태 전이를 시도한다
            #   (routing 상태 Case 에 escalated 를 쓰려다 상태기계에 걸렸다).
            with conn.cursor() as cur:
                cur.execute("SELECT 1 FROM action_requests WHERE action_id=%s AND tenant_id=%s AND case_id=%s",
                            (action_id, principal.tenant_id, case_id))
                if cur.fetchone() is None:
                    raise _error(404, "not_found", "resource not found")

            # ★재검증으로 escalated 를 쓸 수 있는 상태는 waiting_approval 뿐이다.
            #   다른 상태의 승인 요청은 아래 전이에서 상태기계가 판단한다.
            if request.decision == "approved" and case["status"] == "waiting_approval":
                # ★대조 어휘는 도메인 선언에서 가져온다. 이 파일은 무엇을 대조하는지 모른다.
                from app.composition import build_verification
                policy, queries = build_verification()
                mismatches = recheck_before_execution(
                    conn, tenant_id=principal.tenant_id, case=case, action_id=action_id,

                           actor_type="controller", actor_id=actor_id, outbox=outbox)

@use_instance_bindings
async def resume(self, *, tenant_id: str, case_id: UUID, token: str,
                 actor_id: str = "controller", event_id: str | None = None,
                 message: str | None = None, expected_version: int | None = None,
                 resume_route: ResumeRoute | None = None,
                 resume_prepare: ResumePrepare | None = None) -> dict[str, Any]:
    return await self._resume(tenant_id=tenant_id, case_id=case_id, token=token,
                              actor_id=actor_id, event_id=event_id, message=message,
                              expected_version=expected_version, resume_route=resume_route,
                              resume_prepare=resume_prepare)

@use_instance_bindings
async def resume_customer_input(self, *, tenant_id: str, case_id: UUID, customer_id: UUID,
                                 message: str, event_id: str, expected_version: int | None = None,
                                 actor_id: str = "controller",
                                 resume_route: ResumeRoute | None = None,
                                 resume_prepare: ResumePrepare | None = None) -> dict[str, Any]:
    """인증된 웹 고객만 자신의 입력 대기를 재개한다. 공개 토큰 API와 분리한다."""
    return await self._resume(tenant_id=tenant_id, case_id=case_id, token=None,
                              customer_id=customer_id, actor_id=actor_id, event_id=event_id,
                              message=message, expected_version=expected_version, resume_route=resume_route,
                              resume_prepare=resume_prepare)

async def _resume(self, *, tenant_id: str, case_id: UUID, token: str | None,
                  actor_id: str, event_id: str | None, message: str | None,
                  expected_version: int | None, customer_id: UUID | None = None,
                  resume_route: ResumeRoute | None = None,
                  resume_prepare: ResumePrepare | None = None) -> dict[str, Any]:
    if message is not None and not message.strip():
        raise ValueError("customer input must not be blank")
    safe_message = masked(message.strip()) if message is not None else None
    message_hash = self.case_service.token_hash(message.strip()) if message is not None else None
    with self.connection_factory() as conn:
        # 같은 업무의 토큰 검증과 소비는 행 잠금 안에서 처리한다.
        # 읽기 뒤 버전만 재시도하면 다른 답변이 사용한 토큰을 다시 소비할 수 있다.
        with conn.cursor() as cur:
            cur.execute("SELECT 1 FROM customer_cases WHERE tenant_id=%s AND case_id=%s FOR UPDATE",
                        (tenant_id, case_id))
        case = self.repository.get_case(conn, tenant_id=tenant_id, case_id=case_id)
        if case is None:
            raise ControllerError("case not found")
        if token is None and (customer_id is None or str(case["customer_id"]) != str(customer_id)):
            raise ControllerError("customer does not own case")
        try:
            validation = (self.case_service.validate_resume(case, token, event_id=event_id,
                                                             message_hash=message_hash) if token is not None
                          else self.case_service.validate_customer_input(case, event_id=event_id,
                                                                          message_hash=message_hash))
            if validation == "idempotent":
                # 입력은 이미 반영됐지만 원격 실행이 실패한 업무는 다시 실행할 수 있다.
                # 행 잠금을 먼저 풀어 다음 실행의 짧은 트랜잭션을 막지 않는다.
                if case["status"] == CaseStatus.RUNNING:
                    with conn.cursor() as cur:
                        cur.execute("SELECT 1 FROM agent_runs WHERE tenant_id=%s AND case_id=%s "
                                    "AND status IN ('active','running','resuming') LIMIT 1",
                                    (tenant_id, case_id))
                        active = cur.fetchone() is not None
                    if not active:
                        self.require_team(case.get("owner_team_id"), case_id=case_id)
                        conn.rollback()
                        try:
                            return await self.run_case(tenant_id=tenant_id, case_id=case_id, actor_id=actor_id)
                        except ActiveRunError:
                            # 같은 재시도가 먼저 시작된 경우 완료라고 하지 않고 현재 상태를 돌려준다.
                            latest = self.repository.get_case(conn, tenant_id=tenant_id, case_id=case_id) or case
                            return {"case_id": str(case_id), "status": latest["status"],
                                    "version": latest["version"], "idempotent": True}
                return {"case_id": str(case_id), "status": case["status"],
                        "version": case["version"], "idempotent": True}
        except ResumeRequestConflict as exc:
            raise StateConflict(str(exc)) from exc
        except ResumeTokenExpired as exc:
            self.require_team(case.get("owner_team_id"), case_id=case_id)
            try:
                with conn.transaction():
                    transition_case(conn, tenant_id=tenant_id, case_id=case_id,
                                    expected_version=case["version"], event_type=EventType.WAIT_EXPIRED,
                                    payload={"wait_reason": self._wait_reason(case)},
                                    actor_type="controller", actor_id=actor_id)
                conn.commit()
            except InvalidTransition:
                logger.warning("stale resume token ignored for terminal/non-waiting case",
                               extra={"tenant_id": tenant_id, "case_id": str(case_id)})
            raise ControllerError(str(exc)) from exc
        except ResumeTokenError as exc:
            logger.warning("stale resume token ignored; waiting state preserved",
                           extra={"tenant_id": tenant_id, "case_id": str(case_id)})
            raise ControllerError(str(exc)) from exc
        if expected_version is not None and expected_version != case["version"]:
            raise StateConflict("case version changed before customer input")
        self.require_team(case.get("owner_team_id"), case_id=case_id)
        state = case.get("state_json") or {}
        token_hash = self.case_service.token_hash(token) if token is not None else state["resume_token_hash"]
        patch = {"resume_token_used": True, "last_resume_event_id": event_id}
        if safe_message is not None:
            patch["customer_input"] = safe_message
            patch["customer_input_history"] = [*state.get("customer_input_history", []), safe_message]
        if event_id:
            patch["resume_requests"] = [*state.get("resume_requests", []), {
                "request_id": event_id, "message_hash": message_hash,
                "token_hash": token_hash,
            }]
        # 행 잠금 안에서 최종 담당을 먼저 정한다. 실행 불가 시 답변과 토큰을 소비하지 않는다.
        prospective = {**case, "status": CaseStatus.RESUMING, "state_json": {**state, **patch}}
        team_id = case.get("owner_team_id")
        route_patch = {}
        if resume_route is not None and safe_message is not None:
            routing = resume_route(prospective, safe_message)
            if isinstance(routing, dict):
                team_id = routing.get("owner_team_id") or team_id
                route_patch = routing.get("state_patch", {})
                if not isinstance(route_patch, dict):
                    raise ValueError("resume route state patch must be an object")
                allowed = set(self.TEAM_STATE_KEYS) - {"customer_input", "customer_input_history"}
                if set(route_patch) - allowed:
                    raise ValueError("resume route cannot change controller metadata")
            elif routing is not None:
                team_id = routing
        if team_id is not None and not isinstance(team_id, str):
            raise ValueError("resume route owner must be a team id")
        entry = self.require_team(team_id, case_id=case_id)
        routed_case = {**prospective, "state_json": {**prospective["state_json"], **route_patch}}
        capability = self.registry.capability_for(
            entry, case.get("intent"), input_text=safe_message,
            state=self._capability_state(routed_case))
        self.require_team(team_id, capability, case_id=case_id)
        if resume_prepare is not None and safe_message is not None:
            resume_prepare({**routed_case, "owner_team_id": team_id}, safe_message)
        try:
            with conn.transaction():
                transition_case(conn, tenant_id=tenant_id, case_id=case_id,
                                expected_version=case["version"], event_type=EventType.VALID_INPUT,
                                payload={"resume_token_hash": token_hash,
                                         "state_patch": patch}, actor_type="controller", actor_id=actor_id)
                if team_id != case.get("owner_team_id") or route_patch:
                    latest = self.repository.get_case(conn, tenant_id=tenant_id, case_id=case_id)
                    transition_case(conn, tenant_id=tenant_id, case_id=case_id,
                                    expected_version=latest["version"], event_type=EventType.ROUTED,
                                    payload={"owner_team_id": team_id, "capability": capability,
                                             "state_patch": route_patch},
                                    actor_type="controller", actor_id=actor_id)
                # 실행 입구가 RESUMED를 기록해야 TeamTask.resume/재개 지점도 맞는다.
            conn.commit()
        except InvalidTransition:
            logger.warning("stale resume transition ignored",
                           extra={"tenant_id": tenant_id, "case_id": str(case_id)})
            latest = self.repository.get_case(conn, tenant_id=tenant_id, case_id=case_id) or case
            return {"case_id": str(case_id), "status": latest["status"],
                    "version": latest["version"], "stale": True}
    return await self.run_case(tenant_id=tenant_id, case_id=case_id, actor_id=actor_id)

